// Motion Prompt #139 · MIT License (c) 2026 Shohei Ohtaki · https://showheyohtaki.github.io/motion-prompt/#139
//
// Cube transition / キューブ
// Pack: motion2 (Motion graphics moves, part 2) · element 19 · Category: Transitions & highlights
// What happens: Like a turning cube, the front face swings away and the next face comes round.
// Motion spec:
//   - Face A (an "A" on coral) and face B (a "B" on mint), each 250 × 146. 2.35 s each, A→B→A.
//   - Rotation 0→90° at 0.45–1.6 s (1.15 s), cubic ease-in-out, around a vertical axis through the centre of the cube (depth equal to the face width, 250).
//   - Perspective: camera distance 820 px. Each face is drawn as 2 px vertical slices, each sized and placed by its perspective factor.
//   - The face turning away darkens up to 55% (0.55·sinφ); the incoming face starts 55% dark and brightens (0.55·cosφ). The floor shadow follows the visible width.
// When to use it: Use it to show products, plans or screens one after another with a sense of depth.
// Tags: cube, cube-transition, 3d, rotate, transition, perspective
// Size: 539x208 px · Cycle: 4.7 s
// Needs: kit motion2 -> https://showheyohtaki.github.io/motion-prompt/api/v1/kit/motion2.js
// Live demo: https://showheyohtaki.github.io/motion-prompt/#139
//
// cells[i](k, w, h, u): k = CanvasRenderingContext2D (already cleared and wrapped in save/restore by the caller), w,h = size, u = seconds in [0, cycle). The picture depends only on u.
// Element code starts here. CELLS, constants and helpers live in the kit.

// @element 19
// 19 キューブ（立方体が回るように、前の面が奥へ倒れて次の面が現れる）
const CFW = 250, CFH = 146, CF = [mkCanvas(CFW, CFH), mkCanvas(CFW, CFH)];
function cubeFace(i) {
  const g = CF[i].getContext('2d'); g.setTransform(1, 0, 0, 1, 0, 0); g.clearRect(0, 0, CFW, CFH);
  g.fillStyle = i ? C.mint : C.coral; g.fillRect(0, 0, CFW, CFH);
  g.strokeStyle = 'rgba(255,255,255,.35)'; g.lineWidth = 4; g.strokeRect(12, 12, CFW - 24, CFH - 24);
  txt(g, i ? 'B' : 'A', 78, CFH / 2 + 4, `800 104px ${DISP}`, i ? C.navy : '#fff', 'center', 'middle');
  g.fillStyle = i ? C.navy : '#fff'; g.globalAlpha = 0.8; rr(g, 140, 46, 78, 14, 7); g.fill(); g.globalAlpha = 0.45; rr(g, 140, 72, 60, 12, 6); g.fill(); rr(g, 140, 94, 70, 12, 6); g.fill(); g.globalAlpha = 1;
  return CF[i];
}
CELLS[18] = abCell((k, w, h, u, a, b) => {
  stage(k);
  const phi = (Math.PI / 2) * eIO(P(u, TA - 0.05, TB + 0.1)), c = Math.cos(phi), s = Math.sin(phi), HW = CFW / 2, D = 820, X = w / 2, Y = h / 2 - 4;
  const rot = (x, z) => [x * c - z * s, x * s + z * c];
  const FL = rot(-HW, HW), FR = rot(HW, HW), BR = rot(HW, -HW);
  const pj = p => { const f = D / (D - (p[1] - HW)); return [X + p[0] * f, f]; };
  k.fillStyle = 'rgba(0,0,0,.3)'; k.beginPath(); k.ellipse(X, h - 16, HW * (c + s) * 0.95, 7, 0, 0, 7); k.fill();
  const face = (img, P0, P1, shade) => {
    const A0 = pj(P0), A1 = pj(P1); if (A1[0] - A0[0] < 1) return;
    const STEP = 2;
    for (let sx = 0; sx < CFW; sx += STEP) {
      const t0 = sx / CFW, t1 = Math.min(1, (sx + STEP) / CFW);
      const q0 = pj([lerp(P0[0], P1[0], t0), lerp(P0[1], P1[1], t0)]), q1 = pj([lerp(P0[0], P1[0], t1), lerp(P0[1], P1[1], t1)]);
      const hh = CFH * q0[1]; k.drawImage(img, sx, 0, STEP, CFH, q0[0], Y - hh / 2, q1[0] - q0[0] + 0.7, hh);
    }
    if (shade > 0.01) { k.fillStyle = `rgba(8,14,40,${shade})`; k.beginPath(); k.moveTo(A0[0], Y - CFH * A0[1] / 2); k.lineTo(A1[0], Y - CFH * A1[1] / 2); k.lineTo(A1[0], Y + CFH * A1[1] / 2); k.lineTo(A0[0], Y + CFH * A0[1] / 2); k.closePath(); k.fill(); }
  };
  face(cubeFace(a), FL, FR, 0.55 * s);
  face(cubeFace(b), FR, BR, 0.55 * c);
});
